SET local check_function_bodies = off;

CREATE TABLE "public"."calendar_events" (
  "id"          bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "date"        date                     NOT NULL,
  "title"       text,
  "content"     text,
  "type"        text                     DEFAULT 'diary'::text,
  "author_id"   uuid,
  "created_at"  timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()),
  "mood"        text,
  "author_name" text,
  CONSTRAINT "calendar_events_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."calendar_events"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."love_store" (
  "id"          bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "title"       text                     NOT NULL,
  "price"       integer                  NOT NULL,
  "description" text,
  "stock"       integer                  DEFAULT 1,
  "is_active"   boolean                  DEFAULT true,
  "created_at"  timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()),
  "icon_key"    text                     DEFAULT 'heart-beat'::text,
  "bg_color"    text                     DEFAULT 'pink'::text,
  "owner"       text,
  CONSTRAINT "love_store_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."love_store"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."memory_album_entries" (
  "id"           bigint                   GENERATED ALWAYS AS IDENTITY (SEQUENCE NAME "public"."birthday_album_entries_id_seq") NOT NULL,
  "image_path"   text                     NOT NULL,
  "shot_date"    date                     NOT NULL,
  "caption"      text                     NOT NULL DEFAULT ''::text,
  "author_name"  text                     NOT NULL DEFAULT ''::text,
  "created_by"   text                     NOT NULL DEFAULT ''::text,
  "sort_order"   integer,
  "is_published" boolean                  NOT NULL DEFAULT true,
  "created_at"   timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()),
  CONSTRAINT "birthday_album_entries_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."memory_album_entries"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."profiles" (
  "id"         uuid                     NOT NULL,
  "email"      text,
  "nickname"   text,
  "avatar_url" text,
  "points"     integer                  DEFAULT 0,
  "role"       text                     DEFAULT 'user'::text,
  "created_at" timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()),
  CONSTRAINT "profiles_email_unique" UNIQUE (email),
  CONSTRAINT "profiles_nickname_unique" UNIQUE (nickname),
  CONSTRAINT "profiles_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."profiles"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."schedules" (
  "id"          bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "author_name" text                     NOT NULL,
  "title"       text                     NOT NULL,
  "date"        date                     NOT NULL,
  "label"       text                     DEFAULT 'date'::text,
  "completed"   boolean                  DEFAULT false,
  "created_at"  timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()),
  CONSTRAINT "schedules_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."schedules"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."shared_notes" (
  "id"                  bigint                   GENERATED ALWAYS AS IDENTITY NOT NULL,
  "title"               text                     NOT NULL DEFAULT ''::text,
  "content"             text                     NOT NULL DEFAULT ''::text,
  "note_type"           text                     NOT NULL DEFAULT 'note'::text,
  "status"              text                     NOT NULL DEFAULT 'active'::text,
  "is_pinned"           boolean                  NOT NULL DEFAULT false,
  "created_by_nickname" text                     NOT NULL DEFAULT ''::text,
  "updated_by_nickname" text                     NOT NULL DEFAULT ''::text,
  "source_type"         text                     NOT NULL DEFAULT 'manual'::text,
  "source_ref"          text,
  "created_at"          timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()),
  "updated_at"          timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()),
  CONSTRAINT "shared_notes_note_type_check" CHECK ((note_type = ANY (ARRAY['note'::text, 'redeem'::text]))),
  CONSTRAINT "shared_notes_pkey" PRIMARY KEY (id),
  CONSTRAINT "shared_notes_status_check" CHECK ((status = ANY (ARRAY['active'::text, 'done'::text])))
);

ALTER TABLE "public"."shared_notes"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."user_credentials" (
  "id"            bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "username"      text                     NOT NULL,
  "password_hash" text                     NOT NULL,
  "nickname"      text,
  "created_at"    timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()),
  "email"         text,
  CONSTRAINT "user_credentials_pkey" PRIMARY KEY (id),
  CONSTRAINT "user_credentials_username_key" UNIQUE (username)
);

ALTER TABLE "public"."user_credentials"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."user_inventory" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id"    uuid,
  "item_name"  text                     NOT NULL,
  "is_used"    boolean                  DEFAULT false,
  "created_at" timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()),
  "owner_name" text,
  CONSTRAINT "user_inventory_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."user_inventory"
  ENABLE ROW LEVEL SECURITY;

CREATE OR REPLACE FUNCTION public.handle_new_user()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
BEGIN
  INSERT INTO public.profiles (id, email, nickname)
  VALUES (new.id, new.email, NULL)
  ON CONFLICT (email) DO UPDATE SET id = EXCLUDED.id;
  RETURN new;
END;
$function$;

CREATE OR REPLACE FUNCTION public.purchase_store_item (
  p_item_id        bigint,
  p_buyer_nickname text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
    v_item public.love_store%rowtype;
    v_profile public.profiles%rowtype;
    v_inventory public.user_inventory%rowtype;
    v_item_owner_key text;
    v_buyer_key text;
begin
    select *
    into v_item
    from public.love_store
    where id = p_item_id
    for update;

    if not found then
        raise exception '商品不存在';
    end if;

    v_item_owner_key := case
        when lower(coalesce(v_item.owner, '')) in ('gogo', 'boy', 'daddy') then 'gogo'
        else 'gigi'
    end;
    v_buyer_key := case
        when lower(coalesce(p_buyer_nickname, '')) in ('gogo', 'boy', 'daddy') then 'gogo'
        else 'gigi'
    end;

    if v_item_owner_key = v_buyer_key then
        raise exception '不能购买自己上架的商品';
    end if;

    if coalesce(v_item.stock, 0) <= 0 then
        raise exception '库存不足';
    end if;

    select *
    into v_profile
    from public.profiles
    where nickname = p_buyer_nickname
    for update;

    if not found then
        raise exception '找不到购买者资料';
    end if;

    if coalesce(v_profile.points, 0) < v_item.price then
        raise exception '熊熊币不足';
    end if;

    update public.profiles
    set points = points - v_item.price
    where nickname = p_buyer_nickname
    returning * into v_profile;

    update public.love_store
    set stock = stock - 1
    where id = v_item.id
    returning * into v_item;

    insert into public.user_inventory (item_name, is_used, owner_name)
    values (v_item.title, false, p_buyer_nickname)
    returning * into v_inventory;

    return jsonb_build_object(
        'inventory_id', v_inventory.id,
        'remaining_points', v_profile.points,
        'remaining_stock', v_item.stock
    );
end;
$function$;

ALTER TABLE "public"."profiles"
  ADD CONSTRAINT "profiles_id_fkey" FOREIGN KEY (id) REFERENCES auth.users(id);

ALTER TABLE "public"."calendar_events"
  ADD CONSTRAINT "calendar_events_author_id_fkey" FOREIGN KEY (author_id) REFERENCES public.profiles(id);

CREATE INDEX memory_album_entries_created_by_idx ON public.memory_album_entries USING btree (created_by);

CREATE INDEX memory_album_entries_shot_date_idx ON public.memory_album_entries USING btree (shot_date, created_at);

CREATE INDEX shared_notes_pinned_updated_idx ON public.shared_notes USING btree (is_pinned DESC, updated_at DESC, id DESC);

CREATE INDEX shared_notes_source_idx ON public.shared_notes USING btree (source_type, source_ref);

CREATE UNIQUE INDEX uniq_calendar_checkin_author_id_day ON public.calendar_events USING btree (date, author_id)
  WHERE ((TYPE = 'checkin'::text) AND (author_id IS NOT NULL));

CREATE UNIQUE INDEX uniq_calendar_checkin_author_name_day ON public.calendar_events USING btree (date, author_name)
  WHERE ((TYPE = 'checkin'::text) AND (author_name IS NOT NULL));

CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW
  EXECUTE FUNCTION public.handle_new_user();

